source='''def transform(grid):
    out = [row[:] for row in grid]
    width = len(grid[0])
    totals = {}
    for row in grid:
        for cell in row:
            totals[cell] = totals.get(cell, 0) + 1
    full_colors = {row[0] for row in grid if len(row) == width and all(cell == row[0] for cell in row)}
    foregrounds = full_colors & set(totals)
    if not foregrounds:
        return out
    foreground = min(foregrounds, key=totals.get)
    for r, row in enumerate(grid):
        if foreground in row and len(set(row)) > 1:
            out[r] = [cell if cell == foreground else 1 for cell in row]
    return out
'''
